userscript.function:

switch (name) {
    case "SAVE":
        doSave();
        break;
    case "LEGAL_REQUEST":
        doLegalRequest();
        break;
    case "LEGAL_ACCEPT":
        doLegalAccept();
        break;
    case "LEGAL_REJECT":
        doLegalReject();
        break;
    case "ATTACH_REQUEST":
        doAttachRequest();
        break;
    case "BACK":
        doBack();
        break;
    case "COMPLETE":
        doComplete();
        break;
    default:
        break;
}


// 채번 따서 $reqSealInfo에 채번넣고 기본셋팅
$documentList = new Object();
$selectedSealList = new Object();
var smrNumber = getDocumentNumber("SMR");
$reqSealInfo.SMR_NUMBER = smrNumber;
formObj.setValue('SMR_NUMBER', smrNumber);
formObj.setValue('APPLY_TYPE', 'C');
gridObj_title_sub.innerHTML = Sepoa.cache.text.get('SLM_211.GRID_TITLE');
gridObj_title_sub.setAttribute('style', 'font-size:14px;padding-top: 15px;');
gridObj2_title_sub.innerHTML = Sepoa.cache.text.get('SLM_211.GRID_1_TITLE');
gridObj2_title_sub.setAttribute('style', 'font-size:14px;padding-top: 15px;');
gridObj.setColumnHidden(gridObj.getColIndexById('SEAL_TYPE_C'), false);
formObj2.setValue('FOOTER_FLAG', 1);
formObj.setValue('USE_NUMBER', Sepoa.cache.text.get('SLM_221.AXA_USE_TEXT'));
formObj.setValue('SEAL_USE_TYPE', '999');

if(!sUtils.workflow.check('US1638852635132')){
	gridObj.setColumnHidden(gridObj.getColIndexById('COUNT'), 1);
	gridObj.grid_required[gridObj.getColIndexById('COUNT')] = '';
}

//전자 법인, 영문서명인 모듈
if(!sUtils.workflow.check('CS1639451323063')){
	formObj.hideItem("ELECTRON_FLAG");
	formObj.hideItem("ELECTRON_SIGN");  
}

//실물 법인, 영문서명인 모듈
if(!sUtils.workflow.check('CS1639451376543')){
	formObj.hideItem("REAL_FLAG");
	formObj.hideItem("REAL_SIGN");             
}            

doServiceAjax('sepoa.svc.seal.SepoaReqSealService', 'CONNECTION', 'doSelectBasicCorpSeal', {
    SEAL_TYPE: 'C'
}, function(so) {
    if (so.status == 1) {
        $corpSealList = JSON.parse(so.result[0]);
        if (!Sepoa.request.SMR_NUMBER) {
            doAddRow();
        }
    }
});

initBtn();


btnObj.showButton('save,legal_request,legal_accept,legal_reject,attach_request,complete,back', false);
gridObj_btnObj.showButton('rowadd,rowdelete', false);
gridObj2_btnObj.showButton('rowadd_1,rowdelete_1', false);
if (smrStatus != 'T') {
	var alias = '';
    btnObj.showButton('back', true);
    formObj.setViewMode(true);
    formObj._apiConnector('detachAllEvents', []);
    formObj2.setViewMode(true);
    gridObj.setReadOnly(true);
    gridObj.setColumnHidden(gridObj.getColIndexById('MANAGE_IMG'), 1);

	if (Sepoa.request.SMR_NUMBER) {
        btnObj.showButton('back', false);
    }

    if (smrStatus == 'G' && Sepoa.info.DEPARTMENT == Sepoa.config.get('sepoa.rm.dept.code')) {
    	btnObj.showButton('legal_accept,legal_reject',true);
    }

    if (smrStatus == 'D' && Sepoa.info.DEPARTMENT == Sepoa.config.get('sepoa.rm.dept.code')) {
    	alias = 'ATTACH';
        gridObj2.setColumnHidden(gridObj2.getColIndexById('ATTACH_IMG'), 0);
    }

    if (smrStatus == 'C') {
        gridObj2.setColumnHidden(gridObj2.getColIndexById('ATTACH_IMG'), 0);
        gridObj.setColumnHidden(gridObj.getColIndexById('COUNT'), 1);
        if(sUtils.workflow.check('US1638852635132')){
        	gridObj.setColumnHidden(gridObj.getColIndexById('CALC_DOWN_CNT'), 0);
        }
    }

    if(alias != ''){
    	doServiceAjax('sepoa.svc.seal.SepoaReqSealService', 'CONNECTION', 'doSelectNextModule', {
         ALIAS: alias,
         PARENT: 'CSW'
     }, function(so) {
         if (so.status == 1) {
             var moduleArr = JSON.parse(so.result[0]);
             var nextModule = moduleArr.MODULE;
             switch (nextModule) {
                 case "CSW1635988016443":
                     // 결재
                     btnObj.showButton('approval_req', true);
                     break;
                 case "CSW1635988016964":
                     // 법무팀 승인
                     if(alias == 'APPROVAL'){

                     } else {
                     	btnObj.showButton('legal_request', true);
                     }
                     break;
                 case "CSW1635988017548":
                     // 교부서류 첨부
                     if(alias == 'APPROVAL'){

                     } else if(alias == 'LEGAL') {
                     	btnObj.showButton('legal_accept,legal_reject', true);
                     } else {
                     	btnObj.showButton('attach_request', true);
                     }
                     break;
                 case "CSW1635988019236":
                     // 완료
                     if(alias == 'APPROVAL'){

                     } else if(alias == 'LEGAL') {
                     	btnObj.showButton('legal_accept,legal_reject', true);
                     } else {
                     	btnObj.showButton('complete', true);
                     }
                     break;
                 default:
                     break;
             }
         } else {
             Alert(Sepoa.cache.text.get("MESSAGE.1002"));
         }
     });
    }
} else if (smrStatus == 'T') {
    if (moveFlag == 'N') {
        btnObj.showButton('back', true);
    }
    gridObj.setColumnHidden(gridObj.getColIndexById('MANAGE_IMG'), 0);
    doServiceAjax('sepoa.svc.seal.SepoaReqSealService', 'CONNECTION', 'doSelectNextModule', {
        ALIAS: 'CREATE',
        PARENT: 'CSW'
    }, function(so) {
        if (so.status == 1) {
            var moduleArr = JSON.parse(so.result[0]);
            var nextModule = moduleArr.MODULE;
            gridObj_btnObj.showButton('rowadd,rowdelete', true);
            gridObj2_btnObj.showButton('rowadd_1,rowdelete_1', true);
            switch (nextModule) {
                case "CSW1635988016443":
                    // 결재
                    btnObj.showButton('save,approval_req', true);
                    break;
                case "CSW1635988016964":
                    // 법무팀 승인
                    btnObj.showButton('save,legal_request', true);
                    break;
                case "CSW1635988017548":
                    // 교부서류 첨부
                    btnObj.showButton('save,attach_request', true);
                    break;
                case "CSW1635988019236":
                    // 완료
                    btnObj.showButton('save,complete', true);
                    break;
                default:
                    break;
            }
        } else {
            Alert(Sepoa.cache.text.get("MESSAGE.1002"));
        }
    });
}

if (!sUtils.workflow.check('CSW1635988017548')) {
    // 교부서류 안쓰면 교부서류 관련 그리드와 영역 숨김처리
    $('#FOYtSteOidtSteaJNx').hide();
    $('#elrxbmevzvzbmehyDo').hide();
}


btnObj.showButton('back', true);
$documentList = {};
$reqSealInfo = {};
formObj.clear();
formObj2.clear();
gridObj.clearAll();
gridObj2.clearAll();
moveFlag = flag;

doServiceAjax('sepoa.svc.seal.SepoaReqSealService', 'CONNECTION', 'doSelectRequestInfo', {
    SMR_NUMBER: smrNumber,
    APPLY_TYPE: 'C'
}, function(so) {
    if (so.status == 1) {
        var reqData = JSON.parse(so.result[0]);
        var reqSealInfo = reqData[0].REQ_SEAL_INFO;
        var documentList = reqData[0].DOCUMENT_LIST;
        var selectedSealList = reqData[0].SELECTED_SEAL_LIST;
        var attachList = reqData[0].ATTACH_DOCUMENT_LIST;
        formObj.dataMapper(reqSealInfo, 'JSON');
        formObj2.dataMapper(reqSealInfo, 'JSON');
        $reqSealInfo.SMR_NUMBER = reqSealInfo.SMR_NUMBER;

        smrStatus = reqSealInfo.SMR_STATUS;
        initBtn();

        // 구분 세팅
        var reFlagDetail = '';
        if(reqSealInfo.RE_DETAIL == null || reqSealInfo.RE_DETAIL == ''){
        	reFlagDetail = reqSealInfo.RE_FLAG.split(',');
        } else {
        	reFlagDetail = reqSealInfo.RE_DETAIL.split(',');
        }
        for (var i in reFlagDetail) {
            switch (reFlagDetail[i]) {
                case "E":
                    formObj.setValue('ELECTRON_FLAG', 1);
                    continue;
                case "EE":
                    formObj.setValue('ELECTRON_SIGN', 1);
                    continue;
                case "R":
                    formObj.setValue('REAL_FLAG', 1);
                    continue;
                case "RE":
                    formObj.setValue('REAL_SIGN', 1);
                    continue;
            }
        }
        formObj.setValue('USE_NUMBER', Sepoa.cache.text.get('SLM_221.AXA_USE_TEXT'));
		formObj.setValue('SEAL_USE_TYPE', '999');
        // 법적효력문구 세팅
  var legalWatermark = reqSealInfo.LEGAL_WATERMARK;
  if(legalWatermark == 'K'){
  	formObj2.setValue('FOOTER_FLAG', 1);
  }else if(legalWatermark == 'E'){
  	formObj2.setValue('FOOTER_FLAG_EN', 1);
  }                    

        // 날인대상서류 세팅
        for (var i in documentList) {
            var data = documentList[i];
            var maxRowId = dhx4.newId();
            gridObj.addRow(maxRowId, '', gridObj.getRowsNum());
            gridObj.cells(maxRowId, gridObj.getColIndexById('SELECTED')).setValue('1');
            gridObj.cells(maxRowId, gridObj.getColIndexById('SMR_SEQ_TEMP')).setValue('temp_' + maxRowId);
            gridObj.cells(maxRowId, gridObj.getColIndexById('SMD_NUMBER')).setValue(data.SMD_NUMBER);
            gridObj.cells(maxRowId, gridObj.getColIndexById('COUNT')).setValue(data.COUNT);
            gridObj.cells(maxRowId, gridObj.getColIndexById('DOWN_COUNT')).setValue(data.DOWN_COUNT);
            gridObj.cells(maxRowId, gridObj.getColIndexById('SUBJECT')).setValue(data.SUBJECT);
            gridObj.cells(maxRowId, gridObj.getColIndexById('SEAL_TYPE_C')).setValue(data.SEAL_TYPE);
            gridObj.cells(maxRowId, gridObj.getColIndexById('DOC_NUMBER')).setValue(data.SMR_NUMBER + '_' + data.SMD_NUMBER);
            gridObj.cells(maxRowId, gridObj.getColIndexById('CALC_DOWN_CNT')).setValue(Number(data.COUNT) - Number(data.DOWN_COUNT));
            gridObj.showRow(maxRowId);

            $documentList[data.SMD_NUMBER] = data;
            $selectedSealList[data.SMD_NUMBER] = {};
            var sealData = [];

            for (var j in selectedSealList) {
                if (data.SMD_NUMBER == selectedSealList[j].SMD_NUMBER) {
                    selectedSealList[j].ITEM_NAME = selectedSealList[j].SUBJECT;
                    sealData.push(selectedSealList[j]);
                    gridObj.cells(maxRowId, gridObj.getColIndexById("SEAL_MG_DEPT")).setValue(selectedSealList[j].DEPT_NAME);
                    gridObj.cells(maxRowId, gridObj.getColIndexById("SEAL_MG_DEPT_CODE")).setValue(selectedSealList[j].SEAL_MG_DEPT);
                }
            }
            $documentList[data.SMD_NUMBER].SELECT_SEAL_LIST = sealData;
            $selectedSealList[data.SMD_NUMBER].SELECT_SEAL_LIST = sealData;
        }

        var attachDocArr = new Array();
        for (var i in attachList) {
            var maxRowId = dhx4.newId();
            var attachDocData = {};
            gridObj2.addRow(maxRowId, '', gridObj2.getRowsNum());
            gridObj2.cells(maxRowId, gridObj2.getColIndexById('SMI_SEQ_TEMP')).setValue('temp_' + maxRowId);
            gridObj2.cells(maxRowId, gridObj2.getColIndexById('SMI_NUMBER')).setValue(attachList[i].SMI_NUMBER);
            gridObj2.cells(maxRowId, gridObj2.getColIndexById('COUNT')).setValue(attachList[i].COUNT);
            gridObj2.cells(maxRowId, gridObj2.getColIndexById('CONTENTS')).setValue(attachList[i].CONTENTS);
            gridObj2.showRow(maxRowId);

            attachDocData.SMI_NUMBER = attachList[i].SMI_NUMBER;
            attachDocData.DOC_TYPE = attachList[i].DOC_TYPE;
            attachDocData.COUNT = String(attachList[i].COUNT);
            attachDocData.CONTENTS = attachList[i].CONTENTS;

            attachDocArr.push(attachDocData);
        }

        $attachDocumentList = attachDocArr;

        initBtn();
    } else {
        Alert(Sepoa.cache.text.get("MESSAGE.1002"));
    }
});


var tmpFileInput = document.createElement('input');
tmpFileInput.type = 'file';
tmpFileInput.id = 'upload_file';
tmpFileInput.name = 'upload_file';

tmpFileInput.onchange = function(fe) {
    var files = fe.currentTarget.files;
    doUploadDocumentFile(files, smrNumber, smdNumber);
}

tmpFileInput.click();


var config = {
    multiple: false,
    url: window.CONTEXT_NAME + '/SepoaActionController.sux',
    ext: ['pdf'],
    on: {
        callback: function(res) {
            if (res.status == "1") {
                gridObj.cells(selectedGridId, gridObj.getColIndexById("DOC_NUMBER")).setValue(smrNumber + '_' + smdNumber);
                gridObj.cells(selectedGridId, gridObj.getColIndexById("SELECTED")).setValue('1');
                openDocumentFile(smrNumber, smdNumber);
                formObj.checkItem('SEAL_IMG_FLAG');
            } else {
                Alert(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0002'));
                formObj.uncheckItem('SEAL_IMG_FLAG');
            }
        }
    }
}

var params = {
    module: "seal.req",
    action: "doUploadDocumentFile",
    CONNECTION: "TRANSACTION",
    SMR_NUMBER: smrNumber,
    SMD_NUMBER: smdNumber,
    files: files
}

sUtils.multipart.upload(config, params);


var docData = {
    SMR_NUMBER: smrNumber,
    SMD_NUMBER: smdNumber,
    TARGET: "REQ_SEAL",
    SELECT_SEAL_LIST: [$selectedSealList[smdNumber].SELECT_SEAL_LIST]
};
sUtils.popup.modal({
    url: window.CONTEXT_NAME + '/Contract/Module/SealModuleLayout.sux',
    params: {
        DOC_DATA: JSON.stringify(docData),
        SMR_STATUS: smrStatus,
        callback: function(res, config, params) {
            if (res.status == '1') {
                gridObj.cells(selectedGridId, gridObj.getColIndexById("DOC_NUMBER")).setValue(smrNumber + '_' + smdNumber);
            }
        }
    },
    title: Sepoa.cache.text.get('SLM_211.MODIFY_ATTACH_DOC')
});
return;


var sealDeptArray = [];
var sealDeptCodeArray = [];
var manageNumberArray = [];
var gridId = 0;
var deptArray = Sepoa.cache.combo.get('SL0015,' + Sepoa.info.HOUSE_CODE + '#' + Sepoa.info.COMPANY_CODE);
var sealData = [];
var sealType = gridObj.cells(selectedGridId, gridObj.getColIndexById("SEAL_TYPE_C")).getValue();

for (var i in data) {
    var sealObj = new Object();
    var deptLoc = deptArray.find((item, idx) => {
        return item.value == data[i].SEAL_MG_DEPT;
    });
    sealDeptArray.push(deptLoc.text);
    sealDeptCodeArray.push(deptLoc.value);
    sealObj = Object.assign({}, data[i]);
    sealObj.ITEM_NAME = data[i].SUBJECT;
    sealData.push(sealObj);
}

if (sealType != 'C') {
    for (var i in $corpSealList) {
        $corpSealList[i].ITEM_NAME = $corpSealList[i].SUBJECT;
        sealData.push($corpSealList[i]);
    }
}

var smdNumber = gridObj.cells(selectedGridId, gridObj.getColIndexById("SMD_NUMBER")).getValue();
$selectedSealList[smdNumber].SELECT_SEAL_LIST = sealData;
$documentList[smdNumber].SELECT_SEAL_LIST = sealData;

var deptSet = new Set(sealDeptArray);
var deptCodeSet = new Set(sealDeptCodeArray);
var sealDeptStr = Array.from(deptSet).join(',');
var sealDeptCodeStr = Array.from(deptCodeSet).join(',');

gridObj.cells(selectedGridId, gridObj.getColIndexById("SEAL_MG_DEPT")).setValue('');
gridObj.cells(selectedGridId, gridObj.getColIndexById("SEAL_MG_DEPT")).setValue(sealDeptStr);
gridObj.cells(selectedGridId, gridObj.getColIndexById("SEAL_MG_DEPT_CODE")).setValue(sealDeptCodeStr);


var header = this.getColumnId(ind);

var sealType = gridObj.cells(id, gridObj.getColIndexById("SEAL_TYPE_C")).getValue();
selectedGridId = id;

if (header == "MANAGE_IMG" && smrStatus == 'T') {
	var useNumber = formObj.getValue("SEAL_USE_TYPE");

    if (sealType == "") {
        Alert(Sepoa.cache.text.get('SLM_211.MSG_0008'));
        return false;
    }

	if(sUtils.workflow.check('US1637133464814')){
     if (useNumber == "") {
         Alert(Sepoa.cache.text.get('SLM_221.MSG_0035'));
         return false;
     }
	}
    var params = {
        SEAL_TYPE: sealType,
        SEAL_USE_TYPE: useNumber,
        GRID_ROW_ID: id
    };

    PopupOpenPost('/Seal/Document/Common/Popup/SealDocumentWriteSealPopupLayout.sux', params, manageImgPopupCallback, 800, 800, Sepoa.cache.text.get('SLM_221.SELECT_SEAL'));
} else if (header == "ATTACH_IMG") {
    var sealMgDept = gridObj.cells(id, gridObj.getColIndexById("SEAL_MG_DEPT")).getValue();
    var smrNumber = $reqSealInfo.SMR_NUMBER;
    var smdNumber = gridObj.cells(id, gridObj.getColIndexById("SMD_NUMBER")).getValue();
    var docNumber = gridObj.cells(id, gridObj.getColIndexById("DOC_NUMBER")).getValue();

    if (sealType == "" || sealMgDept == "") {
        Alert(Sepoa.cache.text.get('SLM_211.MSG_0009'));
        return false;
    }

    if (docNumber != '') {
        openDocumentFile(smrNumber, smdNumber);
    } else {
        openFileExplorer(smrNumber, smdNumber);
    }
}


switch (name) {
    case "SEAL_USE_TYPE_IMG":
        //doOpenSealUsePopup();
        break;
    default:
        break;
}


formObj2.getSelect(id).options[0].hidden = true;
if (formObj2.getValue(id) == '') {
    formObj2.getSelect(id).options[1].selected = true
}


if (name == 'ELECTRON_FLAG' || name == 'REAL_FLAG' || name == 'ELECTRON_SIGN' || name == 'REAL_SIGN') {
    doChangeFlag(name, state);
    gridObj.setSizes();
}


var reloadFlag = false;

if (name) {
    if (name == 'ELECTRON_FLAG' && state) {
        if (formObj.isItemChecked('REAL_FLAG')) formObj.uncheckItem("REAL_FLAG");
        if (formObj.isItemChecked('REAL_SIGN')) formObj.uncheckItem("REAL_SIGN");
        if (!formObj.isItemChecked('ELECTRON_SIGN')) reloadFlag = true;
    } else if (name == 'REAL_FLAG' && state) {
        if (formObj.isItemChecked('ELECTRON_FLAG')) formObj.uncheckItem("ELECTRON_FLAG");
        if (formObj.isItemChecked('ELECTRON_SIGN')) formObj.uncheckItem("ELECTRON_SIGN");
        if (!formObj.isItemChecked('REAL_SIGN')) reloadFlag = true;
    } else if (name == 'ELECTRON_SIGN' && state) {
        if (formObj.isItemChecked('REAL_SIGN')) formObj.uncheckItem("REAL_SIGN");
        if (formObj.isItemChecked('REAL_FLAG')) formObj.uncheckItem("REAL_FLAG");
        if (!formObj.isItemChecked('ELECTRON_FLAG')) reloadFlag = true;
    } else if (name == 'REAL_SIGN' && state) {
        if (formObj.isItemChecked('ELECTRON_SIGN')) formObj.uncheckItem("ELECTRON_SIGN");
        if (formObj.isItemChecked('ELECTRON_FLAG')) formObj.uncheckItem("ELECTRON_FLAG");
        if (!formObj.isItemChecked('REAL_FLAG')) reloadFlag = true;
    }

    gridObj.grid_required[gridObj.getColIndexById('COUNT')] = formObj.isItemChecked('REAL_FLAG') ? '' : 'NotEmpty';
    gridObj.grid_required[gridObj.getColIndexById('COUNT')] = formObj.isItemChecked('REAL_SIGN') ? '' : 'NotEmpty';

    var eFlagValue = formObj.isItemChecked('ELECTRON_FLAG') ? "1" : "0";
    var rFlagValue = formObj.isItemChecked("REAL_FLAG") ? "1" : "0";
    var eSignValue = formObj.isItemChecked('ELECTRON_SIGN') ? "1" : "0";
    var rSignValue = formObj.isItemChecked("REAL_SIGN") ? "1" : "0";
}

if (!name || reloadFlag) {
    if (name) {
        formObj2.setValue("SUBMIT_TYPE", "");
        formObj2.setValue("RCPT_TYPE", "");
        formObj2.hideItem("RCPT_REMARK");
        formObj2.hideItem("RCPT_REMARK_IMG");
        formObj2.setRequired("RCPT_REMARK", false);
    }
    if (formObj.isItemChecked("ELECTRON_FLAG") || formObj.isItemChecked("ELECTRON_SIGN")) {
        formObj2.reloadComboBox('SUBMIT_TYPE', ['SL0023', '{HOUSE_CODE}#{LANGUAGE}#SM011']);
        formObj2.reloadComboBox('RCPT_TYPE', ['SL0024', '{HOUSE_CODE}#{LANGUAGE}#SM012']);
    } else if (formObj.isItemChecked("REAL_FLAG") || formObj.isItemChecked("REAL_SIGN")) {
        formObj2.reloadComboBox('SUBMIT_TYPE', ['SL0030', '{HOUSE_CODE}#{LANGUAGE}#SM011']);
        formObj2.reloadComboBox('RCPT_TYPE', ['SL0028', '{HOUSE_CODE}#{LANGUAGE}#SM012']);
    }
}


var header = this.getColumnId(cInd);
selectedGridId = id;

if (header == "ATTACH_IMG") {
    var smrNumber = $reqSealInfo.SMR_NUMBER;
    var smiNumber = gridObj2.cells(id, gridObj2.getColIndexById("SMI_NUMBER")).getValue();
    var docNumber = gridObj2.cells(id, gridObj2.getColIndexById("DOC_NUMBER")).getValue();
    if (smrStatus == 'C') {
        openDocumentAttachFile(smrNumber, smiNumber);
    } else if (smrStatus == 'D') {
        openFileAttachExplorer(smrNumber, smiNumber);
    }
}


// 교부서류 파일 보기
var docData = {
    SMR_NUMBER: smrNumber,
    SMI_NUMBER: smiNumber,
    TARGET: "SEAL_ATC",
};
sUtils.popup.modal({
    url: window.CONTEXT_NAME + '/Contract/Module/SealModuleLayout.sux',
    params: {
        DOC_DATA: JSON.stringify(docData),
        SMR_STATUS: smrStatus,
        callback: function(res, config, params) {

        }
    },
    title: Sepoa.cache.text.get('SLM_211.ATTACH_DOC')
});
return;


var tmpFileInput = document.createElement('input');
tmpFileInput.type = 'file';
tmpFileInput.id = 'upload_file';
tmpFileInput.name = 'upload_file';

tmpFileInput.onchange = function(fe) {
    var files = fe.currentTarget.files;
    doUploadAttachDocumentFile(files, smrNumber, smiNumber);
}

tmpFileInput.click();


var config = {
    multiple: false,
    url: window.CONTEXT_NAME + '/SepoaActionController.sux',
    ext: ['pdf', 'PDF', 'docx', 'doc', 'ppt', 'pptx', 'hwp'],
    on: {
        callback: function(res) {
            if (res.status == "1") {
                gridObj2.cells(selectedGridId, gridObj2.getColIndexById("DOC_NUMBER")).setValue(smrNumber + '_' + smiNumber);
            } else {
                Alert(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0002'));
            }
        }
    }
}
var params = {
    module: "seal.req",
    action: "doUploadAttachDocumentFile",
    CONNECTION: "TRANSACTION",
    SMR_NUMBER: smrNumber,
    SMI_NUMBER: smiNumber,
    files: files
}

sUtils.multipart.upload(config, params);


if (name == "FOOTER_FLAG" && state) {
    formObj2.setValue('FOOTER_FLAG_EN', '0');
}

if (name == "FOOTER_FLAG_EN" && state) {
    formObj2.setValue('FOOTER_FLAG', '0');
}


if (!formObj.validate()) {
    Alert(Sepoa.cache.text.get('MESSAGE.0002'));
    return;
}
var formData = Object.assign(formObj.getFormData(), formObj2.getFormData());
// E 전자 법인인감
var elecFlag = formObj.getValue('ELECTRON_FLAG');
// EE 전자 영문서명인
var elecSign = formObj.getValue('ELECTRON_SIGN');
// R 실물 법인인감
var realFlag = formObj.getValue('REAL_FLAG');
// RE 실물 영문서명인
var realSign = formObj.getValue('REAL_SIGN');

if (elecFlag == "1" || elecSign == "1") {
    var flagArr = [];
    formData.RE_FLAG = "E";
    elecFlag = elecFlag == "1" ? "E" : "";
    elecSign = elecSign == "1" ? "EE" : "";
    if (elecFlag != "") {
        flagArr.push(elecFlag);
    }
    if (elecSign != "") {
        flagArr.push(elecSign);
    }

    formData.RE_DETAIL = flagArr.join(",");
} else if (realFlag == "1" || realSign == "1") {
    var flagArr = [];
    formData.RE_FLAG = "R";
    realFlag = realFlag == "1" ? "R" : "";
    realSign = realSign == "1" ? "RE" : "";

    if (realFlag != "") {
        flagArr.push(realFlag);
    }
    if (realSign != "") {
        flagArr.push(realSign);
    }
    formData.RE_DETAIL = flagArr.join(",");
} else {
    Alert(Sepoa.cache.text.get('SLM_211.MSG_0036'));
    return;
}

